<script>
 import {onMount,tick} from 'svelte';
 import {t,getLanguage,setLanguage} from '../i18n.js';
 import {site} from '../content/site.js';
 import {snippets} from '../lab-code.js';
 import GuidedDiagnosis from './GuidedDiagnosis.svelte';
 import ContactForm from './ContactForm.svelte';
 let {services,about}=$props();
 let page=$state('inicio'),selected=$state(null),language=$state(getLanguage()),composer;
 let model=$state({languageRevision:0,contactService:''});
 const copy={pt:{home:'Início',services:'Serviços',projects:'Projetos',contact:'Contato',back:'Voltar',intro:'Um estúdio de tecnologia independente.',title:'Entre a ideia e o possível, existe código.',description:'Desenvolvemos sites e sistemas, conectamos ferramentas e automatizamos processos.',explore:'Conhecer os serviços',about:'Ideias com contexto. Tecnologia com propósito.',diagnosis:'Vamos descobrir por onde começar?',start:'Encontrar meu caminho',diagnosisHint:'Algumas perguntas para organizar sua ideia e preparar uma conversa.',projectsTitle:'Ideias que você pode experimentar.',local:'Projetos autorais. Demonstrações locais, sem operações reais.',demo:'Experimentar',details:'Conhecer o projeto',contactTitle:'O que vamos criar juntos?',deliveries:'Entregas possíveis',talk:'Conversar sobre isso',limits:'Limites da demonstração',decision:'A ideia por trás',theme:'Tema',nav:'Navegação principal'},en:{home:'Home',services:'Services',projects:'Projects',contact:'Contact',back:'Back',intro:'An independent technology studio.',title:'Between an idea and what is possible, there is code.',description:'We build websites and systems, connect tools and automate processes.',explore:'Explore services',about:'Ideas in context. Technology with purpose.',diagnosis:'Where should we start?',start:'Find my direction',diagnosisHint:'A few questions to organize your idea and prepare a conversation.',projectsTitle:'Ideas you can experience.',local:'Original projects. Local demonstrations, without real operations.',demo:'Try it',details:'Explore the project',contactTitle:'What shall we build together?',deliveries:'Possible deliverables',talk:'Let’s talk about this',limits:'Demonstration limits',decision:'The thinking behind it',theme:'Theme',nav:'Main navigation'},es:{home:'Inicio',services:'Servicios',projects:'Proyectos',contact:'Contacto',back:'Volver',intro:'Un estudio de tecnología independiente.',title:'Entre la idea y lo posible, existe código.',description:'Desarrollamos sitios y sistemas, conectamos herramientas y automatizamos procesos.',explore:'Conocer los servicios',about:'Ideas con contexto. Tecnología con propósito.',diagnosis:'¿Por dónde empezamos?',start:'Encontrar mi camino',diagnosisHint:'Algunas preguntas para organizar tu idea y preparar una conversación.',projectsTitle:'Ideas que puedes experimentar.',local:'Proyectos propios. Demostraciones locales, sin operaciones reales.',demo:'Probar',details:'Conocer el proyecto',contactTitle:'¿Qué vamos a crear juntos?',deliveries:'Entregas posibles',talk:'Hablemos de esto',limits:'Límites de la demostración',decision:'La idea detrás',theme:'Tema',nav:'Navegación principal'}};
 const c=$derived(copy[language]);
 const text=key=>{model.languageRevision;return t(key);};
 const destinations=['inicio','servicos','projetos','contato'];
 const labels=$derived([c.home,c.services,c.projects,c.contact]);
 function readRoute(){const [route,id]=location.hash.slice(1).split('/');page=[...destinations,'diagnostico'].includes(route)?route:route==='laboratorio'?'projetos':'inicio';selected=id!==undefined&&/^\d$/.test(id)?Number(id):null;if(selected!==null&&(selected<0||selected>=(page==='servicos'?services.length:site.projects.length)))selected=null;}
 async function go(route,id=null){history.pushState(null,'',`#${route}${id===null?'':`/${id}`}`);readRoute();await focus();}
 async function focus(){await tick();window.scrollTo({top:0,behavior:'instant'});document.querySelector('.phone-main > h1, .phone-home h1, .phone-main > section:not([hidden]) h1, .phone-main > section:not([hidden]) h2')?.focus({preventScroll:true});}
 function demo(index){if(index===3){go('servicos',3);return;}const url=new URL('/lab-preview.html',location.origin);url.hash=encodeURIComponent(JSON.stringify({index,code:snippets[index],language,mobile:true}));window.open(url,'_blank','noopener,noreferrer');}
 async function contact(briefing,topic){await go('contato');composer.receiveBriefing(briefing,topic);}
 onMount(()=>{readRoute();const update=()=>{language=getLanguage();model.languageRevision++;};update();const pop=()=>{readRoute();focus();};document.addEventListener('languagechange',update);window.addEventListener('popstate',pop);return()=>{document.removeEventListener('languagechange',update);window.removeEventListener('popstate',pop);};});
</script>

<div class="phone-app">
 <a class="phone-skip" href="#mobile-main">{c.explore}</a>
 <header class="phone-header"><a href="#inicio" class="phone-brand" onclick={event=>{event.preventDefault();go('inicio');}} aria-label="loui">loui<span>.</span></a><div class="phone-settings"><label class="sr-only" for="mobile-language">{text('Idioma')}</label><select id="mobile-language" value={language} onchange={event=>setLanguage(event.currentTarget.value,false)}><option value="pt">PT</option><option value="en">EN</option><option value="es">ES</option></select><button type="button" class="theme-toggle" aria-label={c.theme}></button></div></header>
 <main id="mobile-main" class="phone-main" tabindex="-1">
  {#if page==='inicio'}
   <section class="phone-home"><p class="phone-intro">{c.intro}</p><h1 tabindex="-1">{c.title}</h1><p class="phone-description">{c.description}</p><button class="phone-primary" onclick={()=>go('servicos')}>{c.explore}<span aria-hidden="true">↗</span></button><div class="phone-about"><h2>{c.about}</h2>{#each about as paragraph}<p>{text(paragraph)}</p>{/each}<a href={site.socials.linkedin} target="_blank" rel="noopener noreferrer">LinkedIn ↗</a><a href={site.socials.github} target="_blank" rel="noopener noreferrer">GitHub ↗</a></div></section>
  {:else if page==='servicos'}
   {#if selected===null}<h1 tabindex="-1">{c.services}</h1><p class="phone-description">{language==='en'?'What do you need to build, connect or simplify?':language==='es'?'¿Qué necesitas crear, conectar o simplificar?':'O que você precisa criar, conectar ou simplificar?'}</p><div class="phone-service-list">{#each services as service,index}<button onclick={()=>go('servicos',index)}><span><strong>{text(service.title)}</strong><small>{text(service.question)}</small></span><span aria-hidden="true">↗</span></button>{/each}</div><aside class="phone-diagnosis-call"><h2>{c.diagnosis}</h2><p>{c.diagnosisHint}</p><button class="phone-primary" onclick={()=>go('diagnostico')}>{c.start}</button></aside>
   {:else}{@const service=services[selected]}<button class="phone-back" onclick={()=>go('servicos')}>‹ {c.back}</button><h1 tabindex="-1">{text(service.title)}</h1><p class="phone-description">{text(service.question)}</p><p>{text(service.description)}</p><h2>{c.deliveries}</h2><ul class="phone-deliveries">{#each service.items as item}<li>{text(item)}</li>{/each}</ul><p>{text(service.scope)}</p>{#if selected<3}<button class="phone-secondary" onclick={()=>demo(selected)}>{c.demo} ↗</button>{/if}<button class="phone-primary" onclick={()=>{model.contactService=service.title;go('contato');}}>{c.talk}</button>{/if}
  {:else if page==='projetos'}
   {#if selected===null}<h1 tabindex="-1">{c.projectsTitle}</h1><p class="phone-description">{c.local}</p><div class="phone-project-list">{#each site.projects as project,index}{@const item=language==='pt'?project:project.translations[language]}<article><div class="phone-project-art art-{index}" aria-hidden="true">{#if index===0}<span class="art-sun"></span><span>luz / studio</span>{:else if index===1}<span class="art-flow">● ─ ● ─ ●</span><span>atende / workflow</span>{:else}<span class="art-sync">↔</span><span>sincronia / crm</span>{/if}</div><p class="phone-category">{item.category}</p><h2>{project.title}</h2><p>{item.summary}</p><button class="phone-secondary" onclick={()=>go('projetos',index)}>{c.details}</button></article>{/each}</div>
   {:else}{@const project=site.projects[selected]}{@const item=language==='pt'?project:project.translations[language]}<button class="phone-back" onclick={()=>go('projetos')}>‹ {c.back}</button><h1 tabindex="-1">{project.title}</h1><p class="phone-description">{item.summary}</p><h2>{c.decision}</h2><p>{item.study.problem}</p><p>{item.study.decision}</p><h2>{c.limits}</h2><p>{item.study.limits}</p><button class="phone-primary" onclick={()=>demo(project.demoIndex)}>{c.demo} ↗</button>{/if}
  {/if}
  <section hidden={page!=='diagnostico'}><button class="phone-back" onclick={()=>go('servicos')}>‹ {c.back}</button><GuidedDiagnosis {model} onDemo={demo} onContact={contact}/></section>
  <section hidden={page!=='contato'}><h1 tabindex="-1">{c.contactTitle}</h1><p class="phone-description">{text('Uma conversa pode ser o começo.')}</p><ContactForm bind:this={composer} {model} translate={t}/><div class="phone-contact-links"><a href={`mailto:${site.contacts.email}`}>{site.contacts.email}</a><a href={site.socials.linkedin} target="_blank" rel="noopener noreferrer">LinkedIn ↗</a></div></section>
 </main>
 <nav class="phone-nav" aria-label={c.nav}>{#each destinations as destination,index}<a href={`#${destination}`} aria-current={(page===destination||(destination==='servicos'&&page==='diagnostico'))?'page':undefined} onclick={event=>{event.preventDefault();go(destination);}}><svg viewBox="0 0 24 24" aria-hidden="true">{#if index===0}<path d="m3 11 9-8 9 8M5 10v11h5v-7h4v7h5V10"/>{:else if index===1}<rect x="4" y="4" width="6" height="6" rx="1"/><rect x="14" y="4" width="6" height="6" rx="1"/><rect x="4" y="14" width="6" height="6" rx="1"/><rect x="14" y="14" width="6" height="6" rx="1"/>{:else if index===2}<path d="M3 7h18v14H3zM8 7V3h8v4M3 12h18"/>{:else}<path d="M4 4h16v12H9l-5 5z"/>{/if}</svg><span>{labels[index]}</span></a>{/each}</nav>
</div>
